const SRC = String.raw`"use strict";
const fs = require("fs");
const path = require("path");

const FILE = path.join(__dirname, "config.json");

function bail(msg) {
  process.stderr.write(msg + "\n");
  process.exit(1);
}

let text;
try {
  text = fs.readFileSync(FILE, "utf8");
} catch (err) {
  bail("MISSING");
}

let probe;
try {
  probe = JSON.parse(text);
} catch (err) {
  bail("INVALID");
}
if (probe === null || typeof probe !== "object" || Array.isArray(probe)) {
  bail("INVALID");
}

function skipWs(s, i) {
  while (i < s.length) {
    const c = s[i];
    if (c === " " || c === "\t" || c === "\n" || c === "\r") i++;
    else break;
  }
  return i;
}

function scanString(s, i) {
  let j = i + 1;
  while (j < s.length) {
    const c = s[j];
    if (c === "\\") { j += 2; continue; }
    if (c === '"') return j + 1;
    j++;
  }
  throw new Error("bad string");
}

function scanValue(s, i) {
  const c = s[i];
  if (c === '"') return scanString(s, i);
  if (c === "{" || c === "[") {
    let depth = 0;
    let j = i;
    while (j < s.length) {
      const ch = s[j];
      if (ch === '"') { j = scanString(s, j); continue; }
      if (ch === "{" || ch === "[") depth++;
      else if (ch === "}" || ch === "]") { depth--; if (depth === 0) return j + 1; }
      j++;
    }
    throw new Error("bad value");
  }
  let j = i;
  while (j < s.length && ",}] \t\n\r".indexOf(s[j]) === -1) j++;
  return j;
}

function compact(raw) {
  let out = "";
  let i = 0;
  while (i < raw.length) {
    const c = raw[i];
    if (c === '"') { const e = scanString(raw, i); out += raw.slice(i, e); i = e; continue; }
    if (c === " " || c === "\t" || c === "\n" || c === "\r") { i++; continue; }
    out += c;
    i++;
  }
  return out;
}

const entries = [];
let i = skipWs(text, 0);
if (text[i] !== "{") bail("INVALID");
i = skipWs(text, i + 1);
while (i < text.length && text[i] !== "}") {
  if (text[i] !== '"') bail("INVALID");
  const keyEnd = scanString(text, i);
  const key = JSON.parse(text.slice(i, keyEnd));
  i = skipWs(text, keyEnd);
  if (text[i] !== ":") bail("INVALID");
  i = skipWs(text, i + 1);
  const valEnd = scanValue(text, i);
  entries.push([key, text.slice(i, valEnd)]);
  i = skipWs(text, valEnd);
  if (text[i] === ",") { i = skipWs(text, i + 1); continue; }
  if (text[i] === "}") break;
  bail("INVALID");
}

const parts = [];
const order = [];
let hasEnabled = false;
let hasVersion = false;

for (const entry of entries) {
  const key = entry[0];
  const raw = entry[1];
  order.push(key);
  if (key === "enabled") { hasEnabled = true; parts.push('"enabled":true'); }
  else if (key === "version") { hasVersion = true; parts.push('"version":2'); }
  else parts.push(JSON.stringify(key) + ":" + compact(raw));
}
if (!hasEnabled) { parts.push('"enabled":true'); order.push("enabled"); }
if (!hasVersion) { parts.push('"version":2'); order.push("version"); }

fs.writeFileSync(FILE, "{" + parts.join(",") + "}\n");
process.stdout.write("OK " + order.join(",") + "\n");
`;

