window.__selfcheck = function () {
  const checks = [];
  const add = function (name, pass, evidence) {
    checks.push({ name: name, pass: !!pass, evidence: String(evidence) });
  };
  try {
    add('three-loaded', THREE && THREE.REVISION,
      THREE ? ('three r' + THREE.REVISION + ' via ' + threeSrc) : ('CDN import failed: ' + loadErr));

