  } catch (e) {
    add('selfcheck-internal', false, 'threw: ' + String((e && e.message) || e));
  }
  const pass = checks.every(function (c) { return c.pass; });
  const res = { checks: checks, pass: pass };
  const el = document.getElementById('selfcheck');
  if (el) el.textContent = JSON.stringify(res);
  document.title = 'SELFCHECK ' + (pass ? 'PASS' : 'FAIL');
  return res;
};

