  ];
  return { vertices: vertices, faces: faces };
}

function asPoint(p, vertices) {
  if (typeof p === 'number') return vertices[p];
  if (Array.isArray(p)) return [p[0], p[1], p[2]];
  return [p.x, p.y, p.z];
}

