const content = `'use strict';

// Unit cube (edge length 1): 8 vertices, 12 triangles, wound CCW seen from outside
// so every face normal points away from the solid.

function buildCube(size) {
  const s = (typeof size === 'number' && size > 0) ? size : 1;
  const positions = [
    [0, 0, 0], [s, 0, 0], [s, s, 0], [0, s, 0],
    [0, 0, s], [s, 0, s], [s, s, s], [0, s, s]
  ];
  const indices = [
    0, 3, 2,  0, 2, 1,   // -Z
    4, 5, 6,  4, 6, 7,   // +Z
    0, 1, 5,  0, 5, 4,   // -Y
    3, 7, 6,  3, 6, 2,   // +Y
    0, 4, 7,  0, 7, 3,   // -X
    1, 2, 6,  1, 6, 5    // +X
  ];
  return { positions: positions, indices: indices };
}

function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function normalize(a) {
  const l = Math.sqrt(dot(a, a));
  return l > 1e-12 ? [a[0] / l, a[1] / l, a[2] / l] : [0, 0, 0];
}

function vertexList(geometry) {
  const src = geometry.positions || geometry.vertices || geometry.points || [];
  if (src.length && typeof src[0] === 'number') {
    const out = [];
    for (let i = 0; i + 2 < src.length; i += 3) out.push([src[i], src[i + 1], src[i + 2]]);
    return out;
  }
  return src;
}

function triangleList(geometry) {
  const f = geometry.faces;
  if (Array.isArray(f) && f.length && Array.isArray(f[0])) {
    return f.map(function (t) { return [t[0], t[1], t[2]]; });
  }
  const idx = geometry.indices || geometry.triangles || [];
  const tris = [];
  for (let i = 0; i + 2 < idx.length; i += 3) tris.push([idx[i], idx[i + 1], idx[i + 2]]);
  return tris;
}

function meshCenter(points) {
  const c = [0, 0, 0];
  for (let i = 0; i < points.length; i++) {
    c[0] += points[i][0]; c[1] += points[i][1]; c[2] += points[i][2];
  }
  const n = points.length || 1;
  return [c[0] / n, c[1] / n, c[2] / n];
}

// A face of a closed convex solid faces outward when its normal points away
// from the body: normal . (faceCentroid - meshCenter) > 0.
function audit(geometry) {
  const points = vertexList(geometry);
  const tris = triangleList(geometry);
  const center = meshCenter(points);
  const faces = tris.length;
  let inwardFaces = 0;

  for (let i = 0; i < faces; i++) {
    const t = tris[i];
    const a = points[t[0]], b = points[t[1]], c = points[t[2]];
    if (!a || !b || !c) { inwardFaces++; continue; }
    const n = normalize(cross(sub(b, a), sub(c, a)));
    const fc = [(a[0] + b[0] + c[0]) / 3, (a[1] + b[1] + c[1]) / 3, (a[2] + b[2] + c[2]) / 3];
    const outward = dot(n, sub(fc, center)) > 0;
    if (!outward) inwardFaces++;
  }

  const outwardFaces = faces - inwardFaces;
  return {
    faces: faces,
    inwardFaces: inwardFaces,
    facesOutwardRatio: faces === 0 ? 0 : outwardFaces / faces
  };
}

function main() {
  const geometry = buildCube(1);
  const result = audit(geometry);
  console.log(JSON.stringify(result));
  console.log('cube: vertices=' + geometry.positions.length +
    ' triangles=' + (geometry.indices.length / 3) +
    ' inwardFaces=' + result.inwardFaces);
}

module.exports = {
  buildCube: buildCube,
  audit: audit,
  geometry: buildCube(1)
};

if (require.main === module) main();
`;

