  B: { A: 4, C: 1, D: 5 },
  C: { A: 2, B: 1, D: 8, E: 10 },
  D: { B: 5, C: 8, E: 2 },
  E: { D: 2, C: 10 },
};

function dijkstra(graph, start, goal) {
  const dist = {};
  const prev = {};
  const visited = new Set();
  for (const n of Object.keys(graph)) dist[n] = Infinity;
  dist[start] = 0;

  while (true) {
    let u = null;
    for (const n of Object.keys(dist)) {
      if (!visited.has(n) && (u === null || dist[n] < dist[u])) u = n;
    }
    if (u === null || dist[u] === Infinity) break;
    visited.add(u);
    if (u === goal) break;
    for (const [v, w] of Object.entries(graph[u] || {})) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        prev[v] = u;
      }
    }
  }

  if (dist[goal] === Infinity) return { dist: Infinity, path: [] };
  const path = [];
  for (let cur = goal; cur !== undefined; cur = prev[cur]) {
    path.unshift(cur);
    if (cur === start) break;
  }
  return { dist: dist[goal], path };
}

const r = dijkstra(graph, 'A', 'E');
console.log(JSON.stringify({ dist: r.dist, path: r.path }));
`;

