const sumjs = `'use strict';
const fs = require('fs');
const file = process.argv[2] || 'data.txt';
const MOD = 1000000007;
let carry = '';
let count = 0n;
let sum = 0;
let max = -1;

function feed(line) {
  const t = line.replace(/\\r/g, '').trim();
  if (t.length === 0) return;
  const n = Number(t);
  if (!Number.isFinite(n)) return;
  count += 1n;
  if (n > max) max = n;
  sum = (sum + (n % MOD)) % MOD;
}

const stream = fs.createReadStream(file, { encoding: 'utf8', highWaterMark: 1 << 16 });
stream.on('data', (chunk) => {
  const s = carry + chunk;
  let start = 0;
  let idx;
  while ((idx = s.indexOf('\\n', start)) !== -1) {
    feed(s.slice(start, idx));
    start = idx + 1;
  }
  carry = s.slice(start);
});
stream.on('end', () => {
  feed(carry);
  const out = { count: Number(count), sum: sum, max: max };
  process.stdout.write(JSON.stringify(out) + '\\n');
});
stream.on('error', (e) => { console.error('ERR', e.message); process.exit(1); });
